    from collections import defaultdict

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    graph = defaultdict(list)
    for i in range(1, m + 1):
        try:
            u, v = map(int, lines[i].split())
            graph[u].append(v)
            graph[v].append(u)
        except:
            break

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            # BFS to find component
            queue = [i]
            visited[i] = True
            size = 0
            while queue:
                curr = queue.pop(0)
                size += 1
                for neighbor in graph[curr]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers up to n
    lucky_numbers = set()
    def generate_lucky(current, length):
        if current > n:
            return
        if current > 0:
            lucky_numbers.add(current)
        if length < 10:
            generate_lucky(current * 10 + 4, length + 1)
            generate_lucky(current * 10 + 7, length + 1)

    generate_lucky(0, 0)

    # If any component size is already lucky, return 0
    for size in component_sizes:
        if size in lucky_numbers:
            return "0\n"

    # Generate all possible sums from subset of components
    # We need to find minimum number of components that sum to a lucky number

    # Sort components and use DP with pruning
    component_sizes.sort(reverse=True)

    # dp[sum] = min components needed to reach this sum
    dp = {}
    dp[0] = 0

    for size in component_sizes:
        new_dp = dp.copy()
        for s, count in dp.items():
            new_sum = s + size
            if new_sum > n:
                continue
            if new_sum in lucky_numbers and (new_sum not in dp or count + 1 < new_dp.get(new_sum, float('inf'))):
                new_dp[new_sum] = count + 1
            else:
                new_dp[new_sum] = min(new_dp.get(new_sum, float('inf')), count + 1)
        dp = new_dp

    # Find minimum roads (components - 1) for lucky number
    min_roads = float('inf')
    for s in lucky_numbers:
        if s in dp and dp[s] >= 1:
            min_roads = min(min_roads, dp[s] - 1)

    if min_roads == float('inf'):
        return "-1\n"
    else:
        return f"{min_roads}\n"
