    # Find independent set
    in_degree = [len(adj[i]) for i in range(n + 1)]
    max_deg = max(in_degree) if max(in_degree) > 0 else 0

    if max_deg >= k:
        # Remove high degree nodes iteratively
        changed = True
        while changed:
            changed = False
            for i in range(1, n + 1):
                if in_degree[i] >= k:
                    # This node can reduce its neighbors' degrees
                    for v in adj[i]:
                        in_degree[v] -= 1
            for i in range(1, n + 1):
                if in_degree[i] >= k:
                    changed = True
                    break
        # Now all degrees are < k, can greedily select independent set
        selected = set()
        used = set()
        for i in range(1, n + 1):
            if i not in used:
                # Check if neighbors are all used
                has_neighbor_in_set = False
                for v in adj[i]:
                    if v in selected:
                        has_neighbor_in_set = True
                        break
                if not has_neighbor_in_set:
                    selected.add(i)
                    used.add(i)
        result = sorted(list(selected))
        if len(result) >= k:
            print(f"1\n{' '.join(map(str, result))}")
            return ""

    # Force selection of at least k independent nodes based on simpler criterion
    selected = set()
    used = set()
    for i in range(1, n + 1):
        if i not in used and len([v for v in adj[i] if v in selected]) == 0:
            selected.add(i)
            used.add(i)
            if len(selected) >= k:
                break

    if len(selected) >= k:
        result = sorted(list(selected))
        print(f"1\n{' '.join(map(str, result))}")
        return ""

    # Final fallback: use coloring or arbitrary selection
    selected = []
    color = [0] * (n + 1)
    for i in range(1, n + 1):
        if color[i] == 0:
            color[i] = 1
            for v in adj[i]:
                if color[v] == 0:
                    color[v] = 2
        elif color[i] == 2:
            selected.append(i)
    if len(selected) >= k:
        print(f"1\n{' '.join(map(str, selected[:k]))}")
        return ""

    # Third fallback
    selected = []
    for i in range(1, n + 1):
        ok = True
        for v in adj[i]:
            if v in selected:
                ok = False
                break
        if ok:
