                    depth[neighbor] = depth[node] + 1
                    up[0][neighbor] = node
                    key = (min(node, neighbor), max(node, neighbor))
                    max_edge[0][neighbor] = mst_edge_info[key]

        # Binary lifting preprocessing
        for j in range(1, 21):
            for i in range(1, n + 1):
                parent_node = up[j - 1][i]
                if parent_node != 0:
                    up[j][i] = up[j - 1][parent_node]
                    max_edge[j][i] = max(max_edge[j - 1][i], max_edge[j - 1][parent_node])
                else:
                    up[j][i] = i
                    max_edge[j][i] = max_edge[j - 1][i]

        def get_lca(u, v):
            if depth[u] < depth[v]:
                u, v = v, u

            diff = depth[u] - depth[v]
            for j in range(21):
                if diff & (1 << j):
                    u = up[j][u]

            if u == v:
                return u

            for j in range(20, -1, -1):
                if up[j][u] != up[j][v]:
                    u = up[j][u]
                    v = up[j][v]

            return up[0][u]

        def get_max_edge_on_path_to_ancestor(node, ancestor_depth):
            path_max = -1
            diff = depth[node] - ancestor_depth
            for j in range(21):
                if diff & (1 << j):
                    path_max = max(path_max, max_edge[j][node])
                    node = up[j][node]
            return path_max

        results = []
        for u, v, w, idx in edges:
            if not in_mst[idx]:
                lca = get_lca(u, v)
                max_w = -1
                if depth[u] > depth[lca]:
                    max_w = max(max_w, get_max_edge_on_path_to_ancestor(u, depth[lca]))
                if depth[v] > depth[lca]:
                    max_w = max(max_w, get_max_edge_on_path_to_ancestor(v, depth[lca]))
                results.append((idx, max_w))

        results.sort(key=lambda x: x[0])

        output_lines = [str(w) for _, w in results]
        return '\n'.join(output_lines) + '\n' if output_lines else ''


