    first_line = lines[0].split()
    n, w, v, u = int(first_line[0]), int(first_line[1]), int(first_line[2]), int(first_line[3])

    points = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        points.append((float(parts[0]), float(parts[1])))

    if len(points) == 0:
        return str(w / u)

    # For a convex polygon moving left with speed v, find minimum crossing time
    # The key insight: at each y, we need to find when x=0 is clear of the polygon
    # Then the pedestrian can reach that y by that time

    def check_y(y):
        """Returns the time when x=0 is first safe at height y, or infinity"""
        max_x_at_y = float('-inf')
        min_x_at_y = float('inf')

        for i in range(n):
            p1 = points[i]
            p2 = points[(i + 1) % n]

            xi, yi = p1
            xj, yj = p2

            if yi == yj:
                # Horizontal edge
                if yi == y:
                    x1 = min(xi, xj)
                    x2 = max(xi, xj)
                    if x1 <= 0 <= x2:
                        return float('inf')
            else:
                # Non-horizontal edge - find x at height y
                if yi <= y <= yj:
                    t = (y - yi) / (yj - yi)
                    x_at_y = xi + t * (xj - xi)
                    if x_at_y == 0:
                        return float('inf')
                    max_x_at_y = max(max_x_at_y, x_at_y)
                    min_x_at_y = min(min_x_at_y, x_at_y)
                elif yj <= y <= yj:
                    pass
                elif y == yi or y == yj:
                    x_at_y = min(xi, xj) if y == min(yi, yj) else min(xj, xi)

        # The rightmost x at height y (for convex polygon)
        # After time t, it's at max_x - vt
        # We need max_x - vt <= 0, so t >= max_x / v

        # If no edge crosses this y (all x > 0 or all x < 0)
        if min_x_at_y > 0:
            return 0.0
        if max_x_at_y < 0:
            return 0.0

        # Otherwise 0 is in the polygon at some time
        return max_x_at_y / v

    # Sample at vertices
    result_time = float('-inf')

    for yi in points:
        time_needed = yi[1] / u
        t_clear = check_y(yi[0])
        if t_clear == float('inf'):
            return str(w / u)
        result_time = max(result_time, time_needed, t_clear)

    # Also check edges
    for i in range(n):
        p1 = points[i]
        p2 = points[(i + 1) % n]

        y1, y2 = p1[1], p2[1]
        if y1 == y2:
            continue

        if y1 < y2:
            y_start, y_end = y1, y2
        else:
            y_start, y_end = y2, y1

        if y_start <= 0 or y_end >= w:
            continue

        # Sample multiple points along the edge
        num_samples = max(1, int((y_end - y_start) * 100))
        for j in range(num_samples):
            t_ratio = j / num_samples
            y_sample = y_start + t_ratio * (y_end - y_start)
            time_needed = y_sample / u
            t_clear = check_y(y_sample)
            if t_clear == float('inf'):
                return str(w / u)
            result_time = max(result_time, time_needed, t_clear)

    if result_time == float('-inf'):
        return str(w / u)

    return str(round(result_time, 10))


