def solution(input_str):
    def complement(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    def reverse(s):
        return s[::-1]

    def canonical(s):
        forms = [s, reverse(s), complement(s), complement(reverse(s))]
        return min(forms)

    n, k_str = input_str.strip().split()
    k = int(k_str)

    total_strings = 1 << n
    num_canonical = 0

    # Count canonical strings by generating in a way to avoid duplicates
    # We generate strings in lexicographical order and track which are canonical
    seen_canonical = set()

    for i in range(total_strings):
        # Convert integer to binary string of length n
        bits = format(i, f'0{n}b')
        # Only process each string once - we count canonical forms
        cls_rep = canonical(bits)
        if cls_rep not in seen_canonical:
            seen_canonical.add(cls_rep)
            num_canonical += 1
            if num_canonical == k:
                return bits + '\n'

    return '-1\n'

