        d = [-1] * (n + 1)
        d[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if d[v] == -1:
                    d[v] = d[u] + 1
                    queue.append(v)
        dist[start] = d

