    max_distance = -1
    best_path = []

    # Try all combinations of 4 cities and all orderings
    # Since n <= 3000, we can optimize by limiting our search
    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if a == b or dist[a][b] == -1:
