    max_distance = -1
    best_path = []

    # Find optimal path through 4 distinct cities
    # O(n^4) but with early skips where paths don't exist
    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if a == b or dist[a][b] == -1:
