Looking at this problem, I need to count labeled trees with n vertices that share exactly k edges with a given tree, for each k from 0 to n-1.

The key insight is using a combinatorial formula: for a forest with c connected components of sizes s₁, s₂, ..., s_c, the number of spanning trees containing all edges of this forest is n^(c-2) × (s₁ × s₂ × ... × s_c).

For exactly k edges from the given tree, I'll iterate through all possible subsets of k edges, compute how many spanning trees contain all of those edges using the formula, and sum them up.

```python
from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    edges = []
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    MOD = 1000000007
    result = [0] * n

    def find(parent, i):
        if parent[i] != i:
            parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent, i, j):
        root_i = find(parent, i)
        root_j = find(parent, j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    def count_with_forest(edge_subset):
        parent = list(range(n + 1))
        for idx in edge_subset:
            union(parent, edges[idx][0], edges[idx][1])

        components = {}
        for i in range(1, n + 1):
            root = find(parent, i)
            components[root] = components.get(root, 0) + 1

        num_components = len(components)
        component_sizes = list(components.values())

        if num_components == 1:
            return 1
        elif num_components == 2:
            return (component_sizes[0] * component_sizes[1]) % MOD
        else:
            prod = 1
            for size in component_sizes:
                prod = (prod * size) % MOD
            term = pow(n, num_components - 2, MOD)
            return (term * prod) % MOD

    for k in range(n):
        total = 0
        for subset in combinations(range(len(edges)), k):
            total = (total + count_with_forest(subset)) % MOD
        result[k] = total

    return ' '.join(map(str, result))
```

