        if consec > k:
            return "NO"

    # Check 2: If all ? as Y, max consecutive N should not exceed k
    s_min = s.replace('?', 'Y')
    consec = 0
    max_min = 0
    for c in s_min:
        if c == 'N':
            consec += 1
            max_min = max(max_min, consec)
        else:
            consec = 0

