                    visited[v] = True
                    parent_map[v] = u
                    if v == target:
                        found_path = v
                        break
                    queue.append(v)
            if found_path:
                break

        return found_path

    def trace_path(target_):
        path = [target_]
        while parent_map[target_]:
            target_ = parent_map[target_]
            path.append(target_)
        return path[::-1]

    res = [[adj_net[u][v] for v in range(len(adj_net))] for u in range(len(adj_net))]

    for _ in range(capacity):
        target = bfs()
        if target is None:
            return paths

        path = trace_path(target)
        res_rev = [[0] * len(adj_net) for _ in range(len(adj_net))]

        # Backtrack and reduce capacity
        curr = target
        while parent_map[curr]:
            prev = parent_map[curr]
            res[prev][curr] -= 1
            res[curr][prev] += 1
            res_rev[prev][prev] += 1
            res_rev[curr][prev] -= 1
            curr = prev

        paths.append(path)

