import math

def solution(input_str: str) -> str:
    """
    Solve the microwave banana problem.

    Args:
        input_str: Input string with n, m and n lines of operations

    Returns:
        Output string with m integers (earliest timestep for each banana count)
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    ops = []
    for i in range(n):
        parts = lines[1 + i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # result[j] = earliest timestep to get j bananas, -1 if impossible
    result = [-1] * (m + 1)

    # Current reachable states (starting from 0 bananas)
    reachable = {0}

    for step, (t, x, y) in enumerate(ops, 1):
        next_reachable = set()

        # Try applying the operation 0 to y times from each reachable state
        for state in reachable:
            if t == 1:  # Type 1: k := ceil(k + x)
                current = state
                for i in range(y + 1):
                    if 0 <= current <= m:
                        next_reachable.add(current)
                    if i < y:
                        current = math.ceil(current + x)
            else:  # Type 2: k := ceil(k * x)
                current = state
                for i in range(y + 1):
                    if 0 <= current <= m:
                        next_reachable.add(current)
                    if i < y:
                        current = math.ceil(current * x)

        # Update reachable states
        reachable.update(next_reachable)

        # Record earliest timestep for newly reached states > 0
        for val in list(next_reachable):
            if 1 <= val <= m and result[val] == -1:
                result[val] = step

    # Return result for bananas 1 to m
    return ' '.join(map(str, result[1:m+1]))
