import math

MOD = 1051131

def solution(input_text):
    lines = input_text.strip().split('\n')
    parts = lines[0].split()
    m, t, s = int(parts[0]), int(parts[1]), int(parts[2])

    a = list(map(int, lines[1].split()))

    n = 2 * m
    idx = 0
    for i in range(s, n):
        a.append((101 * a[idx] + 10007) % 1051131)
        idx += 1

    # Matrix exponentiation
    # M[i][j] = 1 if i == j else gcd(i+1, j+1) for 0-indexed

    size = n
    # Identity matrix
    def mat_mul(A, B):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k] == 0:
                    continue
                for j in range(size):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            result[i][i] = 1
        while p > 0:
            if p & 1:
                result = mat_mul(result, A)
            A = mat_mul(A, A)
            p >>= 1
        return result

    M = [[0] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            if i == j:
                M[i][j] = 1
            else:
                M[i][j] = math.gcd(i + 1, j + 1)

    M_t = mat_pow(M, t)

    ans = 0
    for i in range(size):
        val = 0
        for j in range(size):
            val = (val + a[j] * M_t[j][i]) % MOD
        ans ^= val

    return str(ans) + '\n'
