from collections import deque
import sys

sys.setrecursionlimit(2000000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, x0, y0 = int(first_line[0]), int(first_line[1]), int(first_line[2])

    grid = []
    for i in range(1, len(lines)):
        if i <= n:
            row = list(map(int, lines[i].split()))
            grid.append(row)

    start_pos = (x0 - 1, y0 - 1)

    lit_positions = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                lit_positions.append((i, j))

    if not lit_positions:
        return "YES\n"

    parent = {start_pos: None}
    visited = {start_pos}
    queue = deque([start_pos])

    while queue:
        curr = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nxt = (curr[0] + dx, curr[1] + dy)
            if 0 <= nxt[0] < n and 0 <= nxt[1] < n:
                if nxt not in visited and grid[nxt[0]][nxt[1]] == 1:
                    visited.add(nxt)
                    parent[nxt] = curr
                    queue.append(nxt)

    for pos in lit_positions:
        if pos not in visited:
            return "NO"

    path_to = {}
    for pos in lit_positions:
        p = pos
        path = []
        while p != start_pos:
            p = parent.get(p)
            if p is None:
                return "NO"
            path.append((p[0], p[1], p[0], p[1]))
        path_to[pos] = path

    result = []
    visited_pos = set()

    def dfs(pos):
        if pos in visited_pos:
            return
        visited_pos.add(pos)
        result.append('2')
        if grid[pos[0]][pos[1]] == 1:
            grid[pos[0]][pos[1]] = 0

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nxt = (pos[0] + dx, pos[1] + dy)
            if nxt in lit_positions:
                dfs(nxt)

        result.extend(path_to[pos])

    for pos in lit_positions:
        dfs(pos)

    start_light = True
    if grid[start_pos[0]][start_pos[1]] != 1:
        start_light = False

    if start_light:
        result.append('1')
        result.extend(path_to.get((start_pos[0], start_pos[1]), []))

    return 'YES\n' + ''.join(result)
