    # Use Python's pow for large number computation
    memo = {}

    def is_winning(a, b):
        """Returns True if the current player can win from state (a,b), False otherwise."""
        state = (a, b)
        if state in memo:
            return memo[state]

        # Check if current state already meets threshold (player who made it loses)
        try:
            ways = pow(a, b)
        except OverflowError:
            ways = float('inf')

        if ways >= n:
            memo[state] = False  # Losing position
            return False

        # Check all possible moves - if ANY move leads to losing position for opponent, current is winning
        can_force_opponent_lose = False

        # Move 1: increase a
        new_a, new_b = a + 1, b
        try:
            ways1 = pow(new_a, new_b)
            if ways1 < n and not is_winning(new_a, new_b):
                can_force_opponent_lose = True
        except OverflowError:
            ways1 = float('inf')
            if ways1 >= n:
                pass  # Valid move but leads to losing for next player
            else:
                if not is_winning(new_a, new_b):
                    can_force_opponent_lose = True

        # Move 2: increase b (only needed if not already found winning move)
        if not can_force_opponent_lose:
            new_a, new_b = a, b + 1
            try:
                ways2 = pow(new_a, new_b)
                if ways2 < n and not is_winning(new_a, new_b):
                    can_force_opponent_lose = True
            except OverflowError:
                ways2 = float('inf')
                if ways2 >= n:
                    pass
                else:
                    if not is_winning(new_a, new_b):
                        can_force_opponent_lose = True

        memo[state] = can_force_opponent_lose
        return can_force_opponent_lose

    # If starting position is winning, current player (Stas) wins
    # If losing, current player (Stas) loses (Masha wins)
    result = is_winning(a, b)

    if result:
        return "Stas\n\n"
    else:
        return "Masha\n\n"
