                        s2 = (S[i-1][max_j] + MOD) % MOD
                        total = (total + s1 - s2 + MOD) % MOD
                up[k][l_val][r_val] = total

    # Compute down[k] for k from 2 to n
    for k in range(2, n + 1):
        # 2D prefix sum of down[k-1]
        S = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(1, m):
            for j in range(1, m + 1):
                S[i][j] = (S[i-1][j] + S[i][j-1] - S[i-1][j-1] + down[k-1][i][j]) % MOD

        for l_val in range(1, m):
            for r_val in range(l_val + 1, m + 1):
                # sum down[k-1][i][j] where i <= l_val, j >= r_val, i < j
                total = 0
                for i in range(1, l_val + 1):
                    min_j = max(r_val, i + 1)
