Looking at this problem, I need to determine if we can assign each road to either "inside" (i) or "outside" (o) the ring such that no two roads intersect except at their endpoints.

The key insight is that two roads cross if their endpoints alternate around the ring. When roads cross, one must be placed inside and one must be placed outside to avoid intersection. This creates a constraint that can be modeled as a 2-coloring problem: build an intersection graph where edges represent crossing roads, then check if the graph is bipartite.

```python
def solution(input_string):
    lines = input_string.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b = int(parts[0]), int(parts[1])
        # Normalize so a < b
        if a > b:
            a, b = b, a
        edges.append((a, b))

    def cross(e1, e2):
        """Check if two edges cross on the ring"""
        a1, b1 = e1
        a2, b2 = e2

        # If edges share any endpoint, they don't cross
        if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
            return False

        # Two edges cross if exactly one of the second edge's endpoints
        # falls in the interval (a1, b1) going clockwise from a1 to b1
        c_in = (a1 <= a2 < b1)
        d_in = (a1 <= b2 < b1)

        return c_in != d_in

    # Build intersection graph
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i], edges[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite using iterative BFS
    color = [-1] * m
    possible = True

    for i in range(m):
        if color[i] == -1:
            color[i] = 0
            queue = [i]
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False
                        break
                if not possible:
                    break
            if not possible:
                break

    if not possible:
        return "Impossible"

    # Convert colors to 'i'/'o' output
    result = []
    for i in range(m):
        result.append('i' if color[i] == 0 else 'o')

    return "".join(result)
