                comp_edges[root] = []
            comp_nodes[root].add(u)
            comp_nodes[root].add(v)
            comp_edges[root].append((u, v))

        moves = 0

        for root, nodes in comp_nodes.items():
            k = len(nodes)

            if k == 0:
                continue

            # Build adjacency for this component's directed graph
            adj = {node: [] for node in nodes}
            for u, v in comp_edges[root]:
                if u in nodes:
                    adj[u].append(v)

            # Check for cycle using DFS
            visited = {node: False for node in nodes}
            rec_stack = {node: False for node in nodes}
            has_cycle = False

            def dfs(node):
                nonlocal has_cycle
                if has_cycle:
                    return
                visited[node] = True
                rec_stack[node] = True
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        dfs(neighbor)
                        if has_cycle:
                            return
                    elif rec_stack[neighbor]:
                        has_cycle = True
                rec_stack[node] = False

            for node in list(nodes):
                if not visited[node]:
                    dfs(node)
                if has_cycle:
                    break

            if has_cycle:
                moves += k
            else:
                moves += max(0, k - 1)

        results.append(str(moves))

    return '\n'.join(results)
