        cur = get_dest(start, 1)
        steps = jump - 1 if jump > 1 else 0
        while steps > 0:
            path.append(cur)
            cur = get_dest(cur, 1)
            steps -= 1
        if jump > 0:
            path.append(get_dest(start, jump))
        return path

    max_turns = n * n * 4 + 100
    turn = 0

    def knoc_out_frogs(f, jump):
