        for i in range(n):
            f_idx = i % n
            if not frogs[f_idx]['alive']:
                continue

            jump, dest = frogs[f_idx]['ai'], get_dest(frogs[f_idx]['pos'], frogs[f_idx]['ai'])

            killed = []
