                            killed.append(fid)

            if cur_pos != dest and dest in pos_map:
                for fid in pos_map[dest]:
                    if frogs[fid]['alive'] and fid != f_idx:
                        killed.append(fid)

            frogs[f_idx]['ai'] -= len(killed)
            if dest in pos_map:
                pos_map[dest].remove(f_idx)
            pos_map[frogs[f_idx]['pos']] = pos_map.get(frogs[f_idx]['pos'], [])
            frogs[f_idx]['pos'] = dest

            if dest in pos_map:
                pass
            else:
                for fid in list(pos_map.get(dest, [])):
                    if fid == f_idx:
                        continue
                    frogs[fid]['alive'] = False
                if dest not in pos_map:
