def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    # Check function: can we achieve maximum height <= max_h using at most k*m hits?
    def check(max_h):
        total_hits = 0
        for h, a in bamboos:
            final_height = h + m * a
            if final_height > max_h:
                diff = final_height - max_h
                hits_needed = (diff + p - 1) // p  # Ceiling division
                total_hits += hits_needed

        return total_hits <= k * m

    # Binary search for the minimum achievable maximum height
    left, right = 0, 0
    for h, a in bamboos:
        right = max(right, h + m * a)

    while left < right:
        mid = (left + right) // 2
        if check(mid):
            right = mid
        else:
            left = mid + 1

    return str(left) + '\n'
