Looking at this problem, I need to:
1. Find strongly connected components (SCCs) in the graph
2. Compute the GCD of all cycle lengths in each SCC
3. For each query, check if the required distance change can be achieved

Key insight: For a car starting at vertex `v` with odometer `s_i` that resets at `t_i`, we need to find a cycle of length `L` such that `(s_i + L) ≡ 0 (mod t_i)`, meaning `L ≡ (t_i - s_i) (mod t_i)`. In an SCC, all cycles have lengths that are multiples of the GCD of all cycle lengths in that SCC.

```python
from math import gcd

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if not lines:
        return ""

    n, m = map(int, lines[idx].split())
    idx += 1

    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        if idx < len(lines):
            a, b, l = map(int, lines[idx].split())
            idx += 1
            adj[a].append((b, l))

    q = int(lines[idx]) if idx < len(lines) else 0
    idx += 1

    # Tarjan's algorithm for SCC
    ids = [-1] * (n + 1)
    low = [-1] * (n + 1)
    scc_ids = [-1] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    timer = 0
    scc_count = 0

    def tarjan(u):
        nonlocal timer, scc_count
        ids[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v, _ in adj[u]:
            if ids[v] == -1:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            while stack:
                w = stack.pop()
                on_stack[w] = False
                scc_ids[w] = scc_count
            scc_count += 1

    for i in range(1, n + 1):
        if ids[i] == -1:
            tarjan(i)

    scc_nodes = [[] for _ in range(scc_count)]
    for i in range(1, n + 1):
        scc_nodes[scc_ids[i]].append(i)

    scc_gcd = [0] * scc_count

    for sc in range(scc_count):
        nodes = scc_nodes[sc]
        if len(nodes) <= 1:
            scc_gcd[sc] = 0
            continue

        root = nodes[0]
        dist = {root: 0}
        queue = [root]
        idx_q = 0

        while idx_q < len(queue):
            u = queue[idx_q]
            idx_q += 1
            for v, l in adj[u]:
                if v in nodes and v not in dist:
                    dist[v] = dist[u] + l
                    queue.append(v)

        g = 0
        for u in nodes:
            for v, l in adj[u]:
                if v in nodes and u in dist and v in dist:
                    cycle_len = dist[u] + l - dist[v]
                    g = gcd(g, abs(cycle_len))
        scc_gcd[sc] = g

    results = []
    for _ in range(q):
        if idx >= len(lines):
            break
        v, s, t = map(int, lines[idx].split())
        idx += 1

        if t == 1 or s == 0:
            results.append("YES")
        else:
            scc_id = scc_ids[v]
            g = scc_gcd[scc_id]
            needed = (t - s) % t
            if g == 0:
                results.append("NO")
            else:
                if needed % g == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return '\n'.join(results)
