    if not lines:
        return ""

    try:
        m = int(lines[0])
    except ValueError:
        return ""

    # Generate all valid set endings
    def is_valid_set(a, b):
        """Check if (a, b) is a valid set ending"""
        if a < 1 or b < 1:
            return False

        # Determine winners
        a_wins = a > b and (a - b) >= 2
        b_wins = b > a and (b - a) >= 2

        if not a_wins and not b_wins:
            return False

        # Winner must reach at least 25 points
        return a >= 25 if a_wins else b >= 25

    valid_sets = [(a, b) for a in range(1, 51) for b in range(1, 51)
                  if is_valid_set(a, b)]

    @lru_cache(maxsize=50000)
    def find_combos(ra, rb, sets_left):
        """Find all combinations of sets summing to (ra, rb) in up to sets_left matches"""
        if ra == 0 and rb == 0:
            return [[]]
        if sets_left <= 0:
            return []

        results = []
        for sa, sb in valid_sets:
            if ra >= sa and rb >= sb:
                for rest in find_combos(ra - sa, rb - sb, sets_left - 1):
                    results.append([(sa, sb)] + rest)
        return results

    results = []

