                for combo in find_combos(total_a, total_b, num_sets):
                    a_wins = sum(1 for sa, sb in combo if sa > sb)
                    b_wins = num_sets - a_wins
                    if (a_wins, b_wins) > best_score:
                        best_score = (a_wins, b_wins)
                        best_combo = combo

